import os
import base64
from google.cloud import texttospeech_v1 as texttospeech

def synthesize_ssml(payload, config=None):
    config = config or {}
    client = texttospeech.TextToSpeechClient()
    voice_name = config.get("voice_name", "en-US-Wavenet-D")
    audio_config = texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.MP3
    )
    voice = texttospeech.VoiceSelectionParams(
        language_code=voice_name[:5],
        name=voice_name
    )
    synthesis_input = texttospeech.SynthesisInput(ssml=payload)
    result = client.synthesize_speech(
        input=synthesis_input, voice=voice, audio_config=audio_config
    )
    return base64.b64encode(result.audio_content).decode("utf-8")
